SourceCode.Declaration:
/// <summary>
/// Supervisor review state per counting journal line: the initial count, the recount (once one
/// has been requested and done), the decision and its reason/comment. Written only by
/// HSMobileOpsCountSupervisorService. The line status (MATCH ... CLOSED) is derived from this
/// row plus InventJournalTrans by HSMobileOpsCountSupervisorService::lineStatus, never stored.
///
/// A recount is detected by quantity: each decision remembers the counted quantity
/// (DecisionCountedQty); a different count since then is the recount. A recount that lands on
/// the same number stays RECOUNT_REQUIRED until the supervisor approves it. RecVersion is not
/// used because the DMF import rewrites every line of the journal.
/// </summary>
public class HSMobileOpsCountLineReview extends common
{
}

Method.Source:
public static HSMobileOpsCountLineReview find(InventJournalId _journalId, LineNum _lineNum, boolean _forUpdate = false)
{
    HSMobileOpsCountLineReview review;

    review.selectForUpdate(_forUpdate);
    select firstOnly review
        where review.JournalId == _journalId
           && review.LineNum   == _lineNum;
    return review;
}
